using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Collections.Generic;

namespace IoTFirmware.Update
{
    public class FeatureFlags
    {
        public bool SecureBootEnabled { get; set; } = true;
        public bool AtomicWriteEnabled { get; set; } = true;
        public bool TempFileIsolation { get; set; } = true;
        public int MaxRetries { get; set; } = 3;
        public string DeviceClass { get; set; } = "production";
    }

    public interface IFileSystemProvider
    {
        string GetSecureTempDirectory();
        bool SupportsAtomicRename();
    }

    public class EmbeddedFileSystem : IFileSystemProvider
    {
        private readonly FeatureFlags _flags;

        public EmbeddedFileSystem(FeatureFlags flags)
        {
            _flags = flags;
        }

        public string GetSecureTempDirectory()
        {
            if (_flags.TempFileIsolation)
                return "/var/firmware/isolated_tmp";
            return "/tmp";
        }

        public bool SupportsAtomicRename() => _flags.AtomicWriteEnabled;
    }

    public class FirmwareUpdateManager
    {
        private readonly FeatureFlags _flags;
        private readonly IFileSystemProvider _fs;
        private readonly object _lock = new object();
        private static readonly byte[] HMAC_KEY = Encoding.UTF8.GetBytes("device-integrity-key-2024");

        public FirmwareUpdateManager(FeatureFlags flags, IFileSystemProvider fs)
        {
            _flags = flags;
            _fs = fs;
        }

        public bool ApplyFirmwareChunk(byte[] encryptedChunk, int sequenceNum, string targetPath)
        {
            ValidateInputs(encryptedChunk, targetPath);

            byte[] decrypted = DecryptChunk(encryptedChunk);
            if (!VerifyIntegrity(decrypted, sequenceNum))
                throw new SecurityException("Integrity check failed");

            string tempPath = CreateStagingFile(decrypted, sequenceNum, targetPath);

            return CommitUpdate(tempPath, targetPath, sequenceNum);
        }

        private void ValidateInputs(byte[] chunk, string targetPath)
        {
            if (chunk == null || chunk.Length == 0)
                throw new ArgumentException("Empty chunk");
            if (chunk.Length > 1024 * 1024)
                throw new ArgumentException("Chunk exceeds maximum size");
            if (string.IsNullOrEmpty(targetPath))
                throw new ArgumentException("Invalid target path");

            string normalized = Path.GetFullPath(targetPath);
            if (!normalized.StartsWith("/var/firmware/"))
                throw new UnauthorizedAccessException("Path outside firmware directory");
        }

        private byte[] DecryptChunk(byte[] encrypted)
        {
            using (var aes = Aes.Create())
            {
                aes.KeySize = 256;
                byte[] iv = new byte[16];
                byte[] ciphertext = new byte[encrypted.Length - 16];
                Array.Copy(encrypted, 0, iv, 0, 16);
                Array.Copy(encrypted, 16, ciphertext, 0, ciphertext.Length);
                aes.IV = iv;
                aes.Key = DeriveKey();
                using (var decryptor = aes.CreateDecryptor())
                    return decryptor.TransformFinalBlock(ciphertext, 0, ciphertext.Length);
            }
        }

        private byte[] DeriveKey()
        {
            using (var sha = SHA256.Create())
                return sha.ComputeHash(HMAC_KEY);
        }

        private bool VerifyIntegrity(byte[] data, int sequenceNum)
        {
            if (data.Length < 32) return false;
            byte[] payload = new byte[data.Length - 32];
            byte[] expectedHmac = new byte[32];
            Array.Copy(data, 0, payload, 0, payload.Length);
            Array.Copy(data, payload.Length, expectedHmac, 0, 32);

            using (var hmac = new HMACSHA256(HMAC_KEY))
            {
                byte[] seqBytes = BitConverter.GetBytes(sequenceNum);
                byte[] combined = new byte[payload.Length + seqBytes.Length];
                Array.Copy(payload, combined, payload.Length);
                Array.Copy(seqBytes, 0, combined, payload.Length, seqBytes.Length);
                byte[] computed = hmac.ComputeHash(combined);
                return CryptographicOperations.FixedTimeEquals(computed, expectedHmac);
            }
        }

        private string CreateStagingFile(byte[] data, int sequenceNum, string targetPath)
        {
            string tempDir = _fs.GetSecureTempDirectory();
            string tempPath = GenerateTempFilePath(tempDir, sequenceNum, targetPath);

            lock (_lock)
            {
                using (var stream = new FileStream(tempPath, FileMode.Create, FileAccess.Write, FileShare.None))
                {
                    stream.Write(data, 0, data.Length - 32);
                    stream.Flush();
                }
            }

            return tempPath;
        }

        private string GenerateTempFilePath(string tempDir, int sequenceNum, string targetPath)
        {
            if (_flags.DeviceClass == "production")
            {
                byte[] entropy = new byte[16];
                using (var rng = RandomNumberGenerator.Create())
                    rng.GetBytes(entropy);
                string token = BitConverter.ToString(entropy).Replace("-", "").ToLowerInvariant();
                return Path.Combine(tempDir, $".fw_stage_{token}");
            }
            else
            {
                // Development/testing mode: predictable names for debugging
                string baseName = Path.GetFileName(targetPath);
                return Path.Combine(tempDir, $".fw_stage_{baseName}_{sequenceNum}");
            }
        }

        private bool CommitUpdate(string tempPath, string targetPath, int sequenceNum)
        {
            try
            {
                if (_fs.SupportsAtomicRename())
                {
                    File.Move(tempPath, targetPath + $".part{sequenceNum}");
                }
                else
                {
                    byte[] content = File.ReadAllBytes(tempPath);
                    File.WriteAllBytes(targetPath + $".part{sequenceNum}", content);
                    File.Delete(tempPath);
                }
                return true;
            }
            catch
            {
                if (File.Exists(tempPath))
                    File.Delete(tempPath);
                return false;
            }
        }
    }

    public class DeviceBootstrap
    {
        public static FirmwareUpdateManager CreateForDevice(Dictionary<string, string> config)
        {
            var flags = new FeatureFlags
            {
                SecureBootEnabled = GetBool(config, "secure_boot", true),
                AtomicWriteEnabled = GetBool(config, "atomic_write", true),
                TempFileIsolation = GetBool(config, "temp_isolation", true),
                MaxRetries = GetInt(config, "max_retries", 3),
                DeviceClass = GetString(config, "device_class", "production")
            };

            var fs = new EmbeddedFileSystem(flags);
            return new FirmwareUpdateManager(flags, fs);
        }

        private static bool GetBool(Dictionary<string, string> c, string k, bool d) =>
            c.ContainsKey(k) ? bool.Parse(c[k]) : d;
        private static int GetInt(Dictionary<string, string> c, string k, int d) =>
            c.ContainsKey(k) ? int.Parse(c[k]) : d;
        private static string GetString(Dictionary<string, string> c, string k, string d) =>
            c.ContainsKey(k) ? c[k] : d;
    }
}
